Translate("deDE", "loch-modan", {
	title = "Loch Modan",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Loch Modan ist ein weites Becken aus Hügeln und Kiefernwäldern in Khaz Modan, östlich von {link:dun-morogh}Dun Morogh{/link}. In seinem Herzen liegt {link:the-loch}der Loch{/link}, der große See, der dem Land seinen Namen gibt, an seinem nördlichen Ende vom Stonewroughtdamm zurückgehalten. Die Stadt {link:thelsamar}Thelsamar{/link} steht nahe seinem Westufer. Zwergentürme bewachen die Pässe, die nach Westen nach {link:ironforge}Ironforge{/link}, nach Norden ins {link:wetlands}Sumpfland{/link} und nach Süden zur {link:searing-gorge}Sengenden Schlucht{/link} führen. Es ist ein sanfteres Land als die Schneefelder von Dun Morogh, reich an Erz, Wild und Fisch, und die {link:dwarves}Zwerge{/link} des {link:kingdom-of-ironforge}Königreichs Ironforge{/link} betrachten es seit Langem als ihr Eigen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet, wann die {link:dwarves}Zwerge{/link} sich zuerst an den Ufern des Lochs niederließen oder wann der Stonewroughtdamm errichtet wurde. Das Land ist alt in ihrer Geschichte. Im {link:valley-of-kings}Tal der Könige{/link} stehen zwei große Statuen Wache über der südlichen Straße. Sie ehren Madoran Bronzebeard und Khardros Wildhammer, die ihre Klans im Zeitalter des Kriegs der Drei Hämmer führten. Man erzählt, dass ihre Söhne die Statuen nach diesem Krieg errichteten, um über die Straße nach Süden zu wachen, als Warnung an jeden, der je wieder gegen die Reiche der Zwerge marschieren wollte.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Loch Modan ist ein belagertes Land, und seine Verteidiger sind wenige. Die Reserve von {link:ironforge}Ironforge{/link} wurde abberufen, um an fernen Fronten für die {link:alliance}Allianz{/link} zu kämpfen, und die dem Loch versprochene Verstärkung ist nie eingetroffen. {link:captain-rugelfuss}Hauptmann Rugelfuss{/link} hält {link:stranglethorn-vale}das Tal{/link} der Könige mit einem einzigen Regiment, während die {link:troggs}Troggs{/link} des Stammes {link:stonesplinter-troggs}Splitterstein{/link} aus den südlichen Hügeln hervorquellen und die Grabung der Forscher am See überrennen. {link:ogres}Oger{/link} des Klans {link:mo-grosh-ogres}Mo'grosh{/link} plündern vom Nordosten her. {link:kobolds}Kobolde{/link} haben die {link:silver-stream-mine}Silberbachmine{/link} besetzt. Am schlimmsten ist, dass {link:dark-iron-dwarves}Dunkeleisen{/link}-Saboteure bis an den Damm selbst herangeschlichen sind, und sie haben Freunde unter jenen, denen die {link:dwarves}Zwerge{/link} vertrauen. In {link:thelsamar}Thelsamar{/link} wurde {link:magistrate-bluntnose}Magistrat Bluntnose{/link} gesagt, dass er Monate auf eine Handvoll Soldaten warten müsse. Er hat aufgehört zu warten, und er bezahlt jeden Fremden, der kämpfen will, in guter Münze.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die {link:dwarves}Zwerge{/link} von {link:ironforge}Ironforge{/link}.{/b} Bergsteiger, Bergleute, Fischer und Köche leben in {link:thelsamar}Thelsamar{/link} und bemannen die Türme entlang der Pässe.
• {b}Die Forscherliga.{/b} Von ihrer Niederlassung in Thelsamar aus versorgt die {link:explorers-league}Forscherliga{/link} Prospektor Ironbands Grabung in den Ruinen östlich des Sees.
• {b}Die Jäger der {link:the-farstrider-lodge}Weitschreiter-Lodge{/link}.{/b} Zwerge, {link:humans}Menschen{/link} und eine Hochelfe unterhalten eine Jagdhütte in den östlichen Hügeln.
• {b}Die {link:stonesplinter-troggs}Splitterstein-Troggs{/link}.{/b} Sie halten die südlichen Täler, die Inseln des Lochs und die Ruinen der Ausgrabung.
• {b}Die {link:mo-grosh-ogres}Mo'grosh-Oger{/link}.{/b} Ein Klan von {link:ogres}Ogern{/link} hat seine Festung in den Höhlen des Nordostens errichtet.
• {b}Die {link:tunnel-rat-kobolds}Tunnelratten-Kobolde{/link}.{/b} {link:kobolds}Kobolde{/link} haben sich in den westlichen Vorbergen Baue gegraben und die {link:silver-stream-mine}Silberbachmine{/link} gefüllt.
• {b}Die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link}.{/b} Mineure und Aufrührer lauern um den Damm, und mindestens einer ihrer Agenten verbarg sich unter den eigenen Trägern der Zwerge.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die Drei Hämmer.{/b} Nach dem Krieg der drei Klans wurde der Könige der Bronzebeards und der Wildhammers am südlichen Tor des Lochs in Stein gedacht.
• {b}Der Zweite Krieg.{/b} Als die {link:horde}Horde{/link} im {link:second-war}Zweiten Krieg{/link} Khaz Modan überrannte, fiel das Land am Loch unter die Herrschaft der {link:orcs}Orcs{/link}. Die {link:dwarves}Zwerge{/link} eroberten es zurück, doch die Wracks orcischer Katapulte und Wagen liegen noch immer in den Untiefen und hinter der alten Silbermine.
• {b}Die Ausgrabung.{/b} Die {link:explorers-league}Forscherliga{/link} eröffnete eine Grabung in uralten Ruinen südöstlich des Lochs. Ihre Ausgräber fanden seltsame geschnitzte Götzenbilder, und bald darauf kamen die {link:troggs}Troggs{/link} aus dem Boden herauf.
• {b}Die Gegenwart.{/b} Nun wird {link:the-loch}der Loch{/link} von den wenigen bewacht, die zurückblieben, und von jeder Hilfe, die sie anheuern können.]=],
		},
		{
			title = "Überlieferungen des Lochs",
			text = [=[• {link:thelsamar}Thelsamar{/link} ist berühmt für seine Blutwürste: Bärenfleisch, in Eberdärme gestopft und mit dem Sekret von Spinnen gewürzt. Der Koch besteht darauf, dass es schwerer ist, als es aussieht.
• Die Krokilisken des Lochs sind wegen ihrer Häute und ihres Fleisches begehrt, doch sie haben sich auf den Inseln des Sees verschanzt, und nur wenige Jäger erlegen sie ohne eine Narbe.
• Die Bergsteiger des Lochs trinken Shimmer Stout, das im fernen {link:brewnall-village}Brewnall{/link} gebraut wird. Einer, der es kostete, schwor, es mache seine Glieder so leicht, dass er glaubte, fliegen zu können.
• Im {link:south-gate-pass}Südtorpass{/link} liegt das ganze Jahr über Schnee, obwohl die Ufer des Lochs darunter grün sind.]=],
		},
	},
})

Translate("deDE", "thelsamar", {
	title = "Thelsamar",
	aliases = { "Gasthof Zum Starkbier-Lager" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Thelsamar ist die wichtigste Stadt von {link:loch-modan}Loch Modan{/link}, eine Ansammlung von Steinhäusern nahe dem Westufer des Sees. Ihr Herz ist der Gasthof Zum Starkbier-Lager, und an hungrigen Arbeitern und herumrennenden Kindern mangelt es der Stadt nie. Sie hat eine Schmiede, einen Greifenhorst und eine Niederlassung der {link:explorers-league}Forscherliga{/link}, und in ihrer Straße hängt ein Steckbrief eines Ogerhäuptlings. {link:mountaineer-kadrell}Bergsteiger Kadrell{/link} geht die Straße durch die Stadt ab, und {link:magistrate-bluntnose}Magistrat Bluntnose{/link} hält die Ordnung aufrecht. Thelsamar fehlen viele Annehmlichkeiten von {link:ironforge}Ironforge{/link}: Ihr Schmied hat immer zu wenig Bronze, und er wünscht, irgendein Händler würde Kohle in die Stadt bringen.]=],
		},
	},
})

Translate("deDE", "stonewrought-dam", {
	title = "Der Stonewroughtdamm",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Stonewroughtdamm schließt das nördliche Ende des Lochs ab, eine Mauer aus Zwergenstein, so gewaltig, dass der See selbst an ihr ruht. {link:chief-engineer-hinderweir-vii}Chefingenieur Hinderweir VII.{/link} verwaltet ihn, mit einigen Ingenieuren und Bergsteigern. Die meisten seiner Wachen wurden an die Front geschickt, darunter sein Oberinspektor. Der Verlust ist spürbar. Die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} haben bereits den {link:thandol-span}Thandol-Übergang{/link} zerstört und {link:dun-modr}Dun Modr{/link} im Norden geplündert, und Hinderweir ist sicher, dass der Damm als Nächstes an der Reihe ist. Ihre Mineure wurden auf seiner östlichen Rampe gesichtet.]=],
		},
	},
})

Translate("deDE", "algaz-station", {
	title = "Station Algaz",
	aliases = { "nördlicher Wachturm" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Station Algaz ist der nördliche Wachposten von {link:loch-modan}Loch Modan{/link}. Ihr Turm steht dort, wo der Tunnel des Nordtorpasses von {link:dun-morogh}Dun Morogh{/link} herabkommt, und gleich südlich von {link:dun-algaz}Dun Algaz{/link}, dem Pass, der weiter ins {link:wetlands}Sumpfland{/link} führt. Viele Bergsteiger sind hier stationiert. Von der Spitze des Turms aus beobachtet {link:mountaineer-stormpike}Bergsteiger Stormpike{/link} die Straßen und spricht gern von seinen eigenen Heldentaten. Ein Rüstungsschmied und ein reisender Händler versorgen die Besatzung. Nördlich der Station haben die Bergsteiger, die Dun Algaz bewachen, die Straße voraus voller {link:orcs}Orcs{/link} vorgefunden.]=],
		},
	},
})

Translate("deDE", "silver-stream-mine", {
	title = "Silberbachmine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Silberbachmine liegt im Norden von {link:loch-modan}Loch Modan{/link}, zwischen der {link:algaz-station}Station Algaz{/link} und dem Damm. Sie lieferte den Zwergen viele Jahre lang Silber, bevor sie versiegte. Die Bergarbeiterliga machte sie daraufhin zu einem Lagerhaus und füllte sie mit Kisten voll guter Zwergenwerkzeuge. Nun sind die {link:tunnel-rat-kobolds}Tunnelratten-Kobolde{/link} eingezogen und haben ihre Pfoten auf alles gelegt. Die Bergsteiger wollen die Mine säubern, doch die Liga hätte ihre Ausrüstung gern zuerst herausgeschafft, bevor die Soldaten sie zerbrechen.]=],
		},
	},
})

Translate("deDE", "ironband-s-excavation-site", {
	title = "Ironbands Ausgrabungsstätte",
	aliases = { "Ironbands Ausgrabung" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ironbands Ausgrabungsstätte ist eine Grabung der {link:explorers-league}Forscherliga{/link} in uralten Ruinen südöstlich des Lochs. {link:prospector-ironband}Prospektor Ironband{/link} leitet sie, und {link:magmar-fellhew}Magmar Fellhew{/link} führt die Arbeiten. Die Ausgräber hatten gerade eine große Zahl geschnitzter steinerner Götzenbilder freigelegt, als die {link:stonesplinter-troggs}Splitterstein-Troggs{/link} in den Ruinen auftauchten und sie vertrieben. Die Götzenbilder scheinen die {link:troggs}Troggs{/link} anzuziehen und manche von ihnen in Raserei zu versetzen. Die Ausgräber flohen so schnell, dass sie die meisten ihrer Werkzeuge zurückließen. Ein Trogghäuptling und sein Schamane beherrschen nun die Stätte.]=],
		},
	},
})

Translate("deDE", "mo-grosh-stronghold", {
	title = "Festung Mo'grosh",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Festung Mo'grosh ist ein Nest von Höhlen in den Hügeln nordöstlich des Lochs. Ein Klan von Ogern hat dort sein Lager aufgeschlagen, und von dort aus greifen sie {link:thelsamar}Thelsamar{/link}, den Damm und die Ausgrabung gleichermaßen an. Sie bauen in den Höhlen seltene Kristalle ab. Vor nicht langer Zeit überfielen sie eine Erzkarawane, die aus dem {link:wetlands}Sumpfland{/link} kam, und schafften das Erz in ihr Lager. Ihr Häuptling, {link:chok-sul}Chok'sul{/link}, wird vom Magistrat von Thelsamar gesucht.]=],
		},
	},
})

Translate("deDE", "the-farstrider-lodge", {
	title = "Die Weitschreiter-Lodge",
	aliases = { "Weitschreiter-Lodge" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Weitschreiter-Lodge steht in den östlichen Hügeln von {link:loch-modan}Loch Modan{/link}. Ihre hohen Balken und geschwungenen Dächer sind in elfischem Stil gehalten, und keine Chronik verzeichnet, wer sie errichtete. Heute ist sie eine Hütte der Jäger, in der die Kunst der Jagd über alles geschätzt wird. {link:marek-ironheart}Marek Ironheart{/link} handelt dort mit Krokiliskenhäuten und -fleisch. Eine Hochelfe, {link:vyrin-swiftwind}Vyrin Swiftwind{/link}, behält ihre Gedanken für sich, und ein junger Mensch namens {link:daryl-the-youngling}Daryl{/link} prahlt vor jedem, der zuhören will. Händler verkaufen Bögen und Gewehre an jene, die zum Jagen kommen.]=],
		},
	},
})

Translate("deDE", "valley-of-kings", {
	title = "Tal der Könige",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Tal der Könige ist der südwestliche Winkel von {link:loch-modan}Loch Modan{/link}, wo die Straße vom {link:south-gate-pass}Südtorpass{/link} ins Grüne herabkommt. Zwei große Statuen von Zwergenkönigen, Madoran Bronzebeard und Khardros Wildhammer, stehen über dem Tal und blicken nach Süden. In der Nähe erhebt sich der südliche Wachturm von {link:captain-rugelfuss}Hauptmann Rugelfuss{/link}, dessen Regiment seinen Posten aus Furcht vor einer Invasion nicht zu verlassen wagt. Weiter südlich führt ein verschlossenes Tor zur {link:searing-gorge}Sengenden Schlucht{/link}, und Bergsteiger {link:mountaineer-pebblebitty}Pebblebitty{/link} öffnet es nur für jene, die ihren Wert beweisen.]=],
		},
	},
})

Translate("deDE", "the-loch", {
	title = "Der Loch",
	aliases = { "der Loch" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Loch ist der große See von Khaz Modan, still und kalt unter den Hügeln. Fischer arbeiten an seinem Westufer, und Jäger suchen die Krokilisken, die sich auf seinen Inseln verschanzt haben. Dreschflossen schwimmen in seinen Tiefen. Die Inseln sind nicht sicher: {link:troggs}Troggs{/link} halten die größte von ihnen, und sie fielen über einen gnomischen Flieger her, der in der Nähe ins Wasser stürzte. Altes Wrackgut liegt entlang der Untiefen verstreut, und die Fischer finden zwischen den Trümmern noch immer verlorene Dinge.]=],
		},
	},
})

Translate("deDE", "grizzlepaw-ridge", {
	title = "Grizzlepaw-Grat",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Grizzlepaw-Grat erhebt sich südlich von {link:thelsamar}Thelsamar{/link}, zwischen der Stadt und dem Troggland im Südwesten. Er gehört den Bären. Ihre Höhlen sind über die Hänge verstreut, und unter ihnen haust ein Schwarzbär von großer Gestalt, {link:ol-sooty}Ol' Sooty{/link}, den die Jäger der {link:the-farstrider-lodge}Weitschreiter-Lodge{/link} seit Langem vergeblich zu erlegen versuchen. Reisende auf der Straße darunter behalten {link:razorfen-downs}die Hügel{/link} im Auge, denn der alte Bär kommt manchmal herunter.]=],
		},
	},
})

Translate("deDE", "stonesplinter-valley", {
	title = "Splittersteintal",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Splittersteintal windet sich zwischen den Bergen im Südwesten von {link:loch-modan}Loch Modan{/link}, und es hat den {link:troggs}Troggs{/link}, die es nun bevölkern, seinen Namen gegeben. Ihre Späher beobachten die Straße, ihre Seher und Schädelklopfer halten die südlichen Hügel, und ihr Häuptling {link:grawmug}Grawmug{/link} bleibt in der tiefsten ihrer Höhlen. Bergsteiger, die dieses Land bestreifen, kehren nicht immer zurück. Hier war es, wo {link:mountaineer-ylva}Bergsteigerin Ylva{/link} nach einer solchen verschollenen Streife suchte, und hier fiel sie.]=],
		},
	},
})

Translate("deDE", "south-gate-pass", {
	title = "Südtorpass",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Südtorpass ist der südliche Tunnel zwischen {link:dun-morogh}Dun Morogh{/link} und {link:loch-modan}Loch Modan{/link}. Er verläuft vom Turm des Südtoraußenpostens im Westen bis zum {link:valley-of-kings}Tal der Könige{/link} im Osten, und er ist der kürzeste Weg von {link:ironforge}Ironforge{/link} nach {link:thelsamar}Thelsamar{/link}. Der Durchgang liegt hoch, und das ganze Jahr über sammelt sich Schnee darin. Ein Schamane des Lochs hat nach einem Krug davon geschickt, für ein Werk, das er nicht erklärte. Bergsteiger tragen Fässer mit Starkbier aus Dun Morogh hindurch.]=],
		},
	},
})

Translate("deDE", "captain-rugelfuss", {
	title = "Hauptmann Rugelfuss",
	subtitle = "Hauptmann des Südturms",
	found = "Der südliche Wachturm, Tal der Könige",
	hint = "Sprecht mit dem Hauptmann, der den südlichen Wachturm hält.",
	allegiance = "Königreich Ironforge · Bergsteiger von Ironforge",
	aliases = { "Rugelfuss" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hauptmann Rugelfuss befehligt das Regiment, das das südliche Tor von {link:loch-modan}Loch Modan{/link} bewacht, im Turm unter den Statuen des Tals der Könige. Für Salutieren hat er keine Geduld. Die {link:alliance}Allianz{/link} sei in der Ferne hart bedrängt, sagt er, und das mache die Lande der {link:dwarves}Zwerge{/link} umso kostbarer, während die {link:troggs}Troggs{/link}, die sich aus ihnen erheben, eine ernste Gefahr für den König seien.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Rugelfuss ist der Soldat, der die Tür halten muss. Die Reserve von {link:ironforge}Ironforge{/link} wurde an die Front gerufen, und seine wenigen Bergsteiger können das Tor nicht verlassen, ohne eine Invasion herauszufordern. Also bekämpft er die {link:troggs}Troggs{/link} auf die einzige Weise, die ihm bleibt: indem er an seiner statt Freiwillige in {link:razorfen-downs}die Hügel{/link} schickt.]=],
		},
		{
			title = "Taten",
			text = [=[• Er hält das südliche Tor von {link:loch-modan}Loch Modan{/link} mit einem Bruchteil der Soldaten, die es braucht.
• Er lenkt seine {link:mountaineer-cobbleflint}Bergsteiger Cobbleflint{/link}, Gravelgaw und Wallbang in einem langen Feldzug gegen die {link:stonesplinter-troggs}Splitterstein-Troggs{/link}.
• Er erfährt den Namen des Häuptlings, der den Aufstand der {link:troggs}Troggs{/link} anführt.]=],
		},
	},
	chapters = {
		{
			title = "Die Steinzähne",
			hint = [=[Bringt dem Hauptmann Beweise für in den Hügeln erschlagene Troggs.]=],
			text = [=[An sein Tor gebunden, konnte Rugelfuss den Krieg nicht selbst in {link:razorfen-downs}die Hügel{/link} tragen. Stattdessen bat er um Beweise: die Steinzähne von {link:troggs}Troggs{/link}, die jenseits seiner Mauern erschlagen wurden. Jeder Zahn, der auf seinen Tisch gelegt wurde, bedeutete einen Trogg weniger im Tal und ein kleines Zeichen, dass die {link:dwarves}Zwerge{/link} noch nicht geschlagen waren.]=],
		},
		{
			title = "Der Häuptling der Splitterstein",
			hint = "Schlagt gegen den Anführer des Troggaufstands zu.",
			text = [=[Endlich erfuhren seine Späher, wer den Aufstand anführte. Die {link:troggs}Troggs{/link} folgten einem Häuptling namens {link:grawmug}Grawmug{/link}, der nirgendwohin ohne seine beiden wildesten Wachen ging, Gnasher und Brawler. Rugelfuss wollte alle drei tot sehen. Ohne ihre Anführer, so urteilte er, könnten die Troggs endlich in den Boden zurückgetrieben werden.]=],
		},
		{
			title = "Das gefallene Banner",
			hint = "Erfahrt, was aus Bergsteigerin Ylva geworden ist.",
			text = [=[{link:mountaineer-ylva}Bergsteigerin Ylva{/link} war allein ins Troggland gezogen, um eine Streife zu finden, die nie heimgekehrt war. Man fand sie tot neben einem zertrampelten Banner von {link:ironforge}Ironforge{/link}. Als das Banner wieder aufgerichtet wurde, kam der {link:troggs}Trogg{/link}, der sie getötet hatte, heraus, um ihm entgegenzutreten, und starb. Rugelfuss nahm die Standarte zurück, um sie reinigen und im Turm aufhängen zu lassen. Ylva sei nie eine für Vorsicht gewesen, sagte er. Nun wussten sie es wenigstens.]=],
		},
	},
	mentions = {
		{ text = "Die Troggbedrohung" },
		{
			text = [=[Zur Verteidigung der Lande des Königs, die Jagd auf {link:grawmug}Grawmug{/link}]=],
		},
		{
			text = [=[Zur Verteidigung der Lande des Königs, befohlen über {link:mountaineer-cobbleflint}Cobbleflint{/link}]=],
		},
		{ text = "Banner der Gefallenen" },
		{ text = "Nachschub für die Front, Waffen für seine Bergsteiger" },
	},
	bonds = {
		{ id = "mountaineer-cobbleflint", name = "Bergsteiger Cobbleflint", note = "dient in seinem Turm" },
		{ id = "grawmug", name = "Grawmug", note = "der Häuptling, den er tot sehen will" },
		{ id = "mountaineer-ylva", name = "Bergsteigerin Ylva", note = "fiel im Troggland" },
		{ id = "headsplitter", name = "Headsplitter", note = "tötete Ylva" },
		{ id = "magni-bronzebeard", name = "Magni Bronzebeard", note = "sein König" },
	},
})

Translate("deDE", "chief-engineer-hinderweir-vii", {
	title = "Chefingenieur Hinderweir VII.",
	subtitle = "Hüter des Stonewroughtdamms",
	found = "Oben auf dem Stonewroughtdamm",
	hint = "Sprecht mit dem Chefingenieur, der über den Damm wacht.",
	allegiance = "Königreich Ironforge",
	aliases = { "Hinderweir" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Chefingenieur Hinderweir VII. verwaltet den Stonewroughtdamm, die große Mauer aus Stein, die den Loch zurückhält. Er ist der Siebte seines Namens, der diesen Titel trägt, und keine Chronik verzeichnet die sechs vor ihm. Er ist ein besorgter {link:dwarves}Zwerg{/link}, und er hat Grund dazu. Sein bester Inspektor und die meisten seiner Wachen wurden an die Front der {link:alliance}Allianz{/link} geschickt, und die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} regen sich im Norden.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Hinderweir erkennt das Muster, das anderen entgeht. Zuerst wurde der {link:thandol-span}Thandol-Übergang{/link} zerstört, dann wurde {link:dun-modr}Dun Modr{/link} geplündert. Er zweifelt nicht daran, dass der Damm das nächste Ziel des Dunkeleisenklans ist, und wenn er fällt, fällt {link:the-loch}der Loch{/link} mit ihm.]=],
		},
		{
			title = "Taten",
			text = [=[• Er wacht mit einer dünnen Wache über den Stonewroughtdamm.
• Er schickt eine Probe des Dunkeleisenpulvers an den Sprengstoffexperten von {link:dun-modr}Dun Modr{/link}.
• Er bereitet die Mischung zu, die den Damm vor einer Ladung der {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} rettet.]=],
		},
	},
	chapters = {
		{
			title = "Eine Spur auf der Rampe",
			hint = [=[Durchsucht die östliche Rampe des Damms nach Zeichen der Dunkeleisenzwerge.]=],
			text = [=[{link:dark-iron-dwarves}Dunkeleisen{/link}-Mineure waren auf der östlichen Rampe des Damms gesichtet worden. Unter dem, was sie zurückließen, war ein Fass mit einem seltsam riechenden Pulver. Hinderweir hielt es für eine Art Sprengstoff, und er schickte eine Probe nach Norden durch das Algaz-Tor zu {link:ashlan-stonesmirk}Ashlan Stonesmirk{/link}, dem Pulvermeister des Regiments in {link:dun-modr}Dun Modr{/link}, mit der Anweisung, auf den Straßen zu bleiben.]=],
		},
		{
			title = "Seaforium",
			hint = "Erfahrt, was das Pulver der Dunkeleisenzwerge wirklich ist.",
			text = [=[Stonesmirk erkannte das Pulver an seinen silbernen Kristallen und seinem Geruch: Seaforium. Trocken war es harmlos. Nass konnte es einen Berg zerreißen. Er schickte ein entschärfendes Kolloid zurück und Nachricht darüber, was sonst noch gebraucht wurde: das Gift der Lauerspinnen aus den Hügeln, die Träne eines Krokilisken und ein seltener Kristall von der Art, wie ihn die {link:mo-grosh-ogres}Mo'grosh-Oger{/link} abbauen.]=],
		},
		{
			title = "Unter dem Damm",
			hint = "Rettet den Stonewroughtdamm.",
			text = [=[Bevor die Mischung fertig war, sah Hinderweir {link:dark-iron-dwarves}Dunkeleisen{/link}-Aufrührer mit einem großen Fass auf den Damm zuschwimmen, und kein Bergsteiger war zur Stelle, um sie aufzuhalten. Die Ladung lag am Fuß des Damms, unter Wasser, und die Mischung wurde rechtzeitig hineingerührt. Der Damm war gerettet. Hinderweir gab nicht vor, dass er für immer gerettet sei.]=],
		},
	},
	mentions = {
		{ text = "Eine dunkle Bedrohung zieht auf, die Mineure auf der Rampe" },
		{ text = "Eine dunkle Bedrohung zieht auf, das seltsame Pulver" },
		{
			text = [=[Eine dunkle Bedrohung zieht auf, der Weg nach {link:dun-modr}Dun Modr{/link}]=],
		},
		{ text = "Eine dunkle Bedrohung zieht auf, das entschärfende Kolloid" },
		{ text = "Eine dunkle Bedrohung zieht auf, die drei Zutaten" },
		{ text = "Eine dunkle Bedrohung zieht auf, das Fass unter Wasser" },
		{ text = "Eine dunkle Bedrohung zieht auf, der gerettete Damm" },
	},
	bonds = {
		{ id = "ashlan-stonesmirk", name = "Ashlan Stonesmirk", note = "der Sprengstoffexperte von Dun Modr" },
		{ id = "chok-sul", name = "Chok'sul", note = "seine Oger halten die Kristalle" },
	},
})

Translate("deDE", "prospector-ironband", {
	title = "Prospektor Ironband",
	subtitle = "Prospektor der Forscherliga",
	found = "Ironbands Ausgrabungsstätte",
	hint = [=[Findet den Prospektor, dessen Grabung südöstlich des Lochs liegt.]=],
	allegiance = "Forscherliga",
	aliases = { "Ironband", "Darteus Ironband" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Prospektor Darteus Ironband leitet die Grabung der {link:explorers-league}Forscherliga{/link} in den uralten Ruinen südöstlich des Lochs. Er ist stämmig und ehrlich, und er schätzt Ergebnisse. In letzter Zeit hatte er wenige. Die {link:stonesplinter-troggs}Splitterstein-Troggs{/link} haben seine Stätte überrannt, sein Sprengpulver kommt nie an, und einer seiner Mitprospektoren im Süden ist verstummt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Ironband ist ein Gelehrter im Feld. Er glaubt, dass die geschnitzten Götzenbilder seiner Grabung eine Verbindung zwischen den {link:troggs}Troggs{/link} und den Titanen offenbaren könnten, und er verfolgt diese Frage von {link:loch-modan}Loch Modan{/link} bis ins {link:badlands}Ödland{/link}. Was er erfährt, erreicht die Liga in {link:ironforge}Ironforge{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er leitet die Ausgrabung und schreibt ihre Berichte für die Liga.
• Er bittet immer wieder um Sprengpulver, das abgeschickt wird und nie ankommt.
• Er lässt Nachricht über Prospektor Agmond einholen, der die Grabungen der Liga im {link:badlands}Ödland{/link} leitete.]=],
		},
	},
	chapters = {
		{
			title = "Die geschnitzten Götzenbilder",
			hint = "Bringt den Bericht des Prospektors nach Thelsamar.",
			text = [=[Ironbands Bericht ist kurz und geduldig. Die Grabung geht weiter, verlangsamt durch {link:troggs}Troggs{/link}, die angriffslustiger sind als gewöhnlich. Die meisten Funde sind interessant und nicht mehr. Einer nicht: Die geschnitzten Götzenbilder ziehen die Troggs an und versetzen manche von ihnen in Raserei. Weitere Untersuchungen sind nötig. Und noch einmal: Wo bleibt sein Sprengpulver?]=],
		},
		{
			title = "Das verschwundene Pulver",
			hint = "Geleitet das Pulver sicher zur Ausgrabung.",
			text = [=[{link:jern-hornhelm}Jern Hornhelm{/link} hatte Wochen zuvor Pulver geschickt, und es kam nie an. Die nächste Lieferung ging mit Trägern entlang der Biegung des Lochs, und auf der Straße schlugen die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} zu. Einer der Träger, Saean, war ihr Mann, obwohl er fast ein Jahr lang an der Seite der anderen gearbeitet hatte. Als Miran den Rest des Pulvers endlich durchbrachte, war Ironband froh darüber und zugleich beunruhigt, dass die Dunkeleisenzwerge Freunde hatten, die an solche Dinge herankamen.]=],
		},
		{
			title = "Das Schicksal Agmonds",
			hint = "Erfahrt, was Prospektor Agmond im Ödland widerfuhr.",
			text = [=[Agmonds Leichnam wurde im {link:badlands}Ödland{/link} gefunden, zerschmettert und abgenagt, mit einem einzigen Wort, das seine Hand in den Sandstein gekratzt hatte: {link:murdaloc}Murdaloc{/link}. Ironband betrauerte ihn als Kämpfer mit dickem Schädel und hartem Schlag. Er fürchtete, dass die Urnen, die Agmonds Ausgräber gefunden hatten, die {link:troggs}Troggs{/link} aufgestört hatten, genau wie seine eigenen Götzenbilder.]=],
		},
	},
	mentions = {
		{ text = "Fortschrittsbericht der Ausgrabung" },
		{ text = "Pulver für Ironband" },
		{ text = "Schutz der Lieferung" },
		{ text = "Grabungswerkzeuge, aus den Ruinen geborgen" },
		{ text = "Ironband braucht Euch!" },
		{ text = "Findet Agmond" },
		{ text = "{link:murdaloc}Murdaloc{/link}" },
		{ text = "Agmonds Schicksal" },
	},
	bonds = {
		{ id = "magmar-fellhew", name = "Magmar Fellhew", note = "leitet seine Stätte" },
		{ id = "jern-hornhelm", name = "Jern Hornhelm", note = "sein Kontakt in Thelsamar" },
		{ id = "prospector-stormpike", name = "Prospektor Stormpike", note = "schickt ihm Hilfe aus Ironforge" },
		{ id = "stonesplinter-troggs", name = "Splitterstein-Troggs", note = "halten seine Grabung" },
	},
})

Translate("deDE", "magistrate-bluntnose", {
	title = "Magistrat Bluntnose",
	subtitle = "Magistrat von Thelsamar",
	found = "Thelsamar",
	hint = "Sprecht mit dem Magistrat, der Thelsamar regiert.",
	allegiance = "Thelsamar · Königreich Ironforge",
	aliases = { "Bluntnose" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Magistrat Bluntnose regiert {link:thelsamar}Thelsamar{/link}, und seine Geduld mit {link:ironforge}Ironforge{/link} schwindet. Es dauerte zwei Monate, bis er erfuhr, dass man der Stadt ein paar Soldaten überlassen würde, und man hat ihm gesagt, dass es noch zwei weitere dauern werde, bis sie eintreffen. Unterdessen liegen Thelsamar, die Ausgrabung und der Damm offen für jeden Angriff.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Bluntnose ist die Stimme des einfachen Volkes am Loch. Wo die Hauptmänner um Soldaten bitten, die nie kommen, greift der Magistrat in die Stadtkasse und heuert an, wer immer kämpfen will. Durch ihn geht die Verteidigung von {link:loch-modan}Loch Modan{/link} in die Hände von Fremden über.]=],
		},
		{
			title = "Taten",
			text = [=[• Er heuert Söldner gegen die {link:mo-grosh-ogres}Mo'grosh-Oger{/link} im Nordosten an.
• Er setzt ein Kopfgeld auf {link:chok-sul}Chok'sul{/link} aus, den {link:ogres}Oger{/link}, der seiner Meinung nach die Angriffe auf seine Stadt anführt.
• Er will sich gegen die {link:troggs}Troggs{/link} wenden, sobald mit den Ogern abgerechnet ist.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Wenig ist über Bluntnoses Leben vor seinem Amt geschrieben. Dieser Eintrag verzeichnet nur, was seine Stadt und seine Befehle offenbaren.]=],
		},
	},
	chapters = {
		{
			title = "Angeheuerte Waffen",
			hint = [=[Nehmt die Münzen des Magistrats und bekämpft die Oger im Nordosten.]=],
			text = [=[Die {link:ogres}Oger{/link} hatten ihr Lager am nordöstlichen Ufer des Sees aufgeschlagen, und es gab niemanden, den man gegen sie schicken konnte. Also schickte Bluntnose Fremde. Als sie mit der Nachricht von erschlagenen Ogern zurückkehrten, war er hocherfreut. Mit den Ogern im Griff, sagte er, könne sich die Stadt endlich gegen die {link:troggs}Troggs{/link} wenden.]=],
		},
		{
			title = "Der Kopf von Chok'sul",
			hint = "Folgt dem Steckbrief, der in Thelsamar hängt.",
			text = [=[In {link:thelsamar}Thelsamar{/link} hängt ein Aushang unter dem Siegel des Magistrats. Er nennt {link:chok-sul}Chok'sul{/link}, den {link:ogres}Oger{/link}, von dem man glaubt, dass er die Überfälle auf die Stadt, den Damm und die Grabung anführt und plant, und er verspricht Münzen für den Beweis seines Todes. Als ihm dieser Beweis vorgelegt wurde, schreckte Bluntnose bei dem Anblick zurück und zahlte dann gern.]=],
		},
	},
	mentions = {
		{ text = "Söldner" },
		{ text = "GESUCHT: {link:chok-sul}Chok'sul{/link}" },
	},
	bonds = {
		{ id = "chok-sul", name = "Chok'sul", note = "der Oger, den er tot sehen will" },
		{ id = "mountaineer-kadrell", name = "Bergsteiger Kadrell", note = "hält die Straße durch seine Stadt" },
	},
})

