	},
	mentions = {
		{ text = "Fortschrittsbericht der Ausgrabung" },
		{ text = "Meldet Euch in {link:ironforge}Ironforge{/link}" },
		{ text = "Pulver für {link:prospector-ironband}Ironband{/link}" },
