	},
	bonds = {
		{ id = "norric-lochthane", name = "Norric Lochthane", note = "ihr alter Mentor" },
	},
})

Translate("deDE", "stonesplinter-troggs", {
	title = "Splitterstein-Troggs",
	aliases = { "Splitterstein", "Splitterstein-Troggs", "Stamm der Splitterstein" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Splitterstein sind die {link:troggs}Troggs{/link} von {link:loch-modan}Loch Modan{/link}. Sie haben ihren Namen vom {link:stonesplinter-valley}Splittersteintal{/link} im Südwesten, und sie sind die größte Gefahr, der sich {link:the-loch}der Loch{/link} gegenübersieht. Keine Chronik verzeichnet, wann sie hier zuerst aus den tiefen Orten heraufkamen.]=],
		},
		{
			title = "Ihre Lande",
			text = [=[Sie halten das {link:stonesplinter-valley}Splittersteintal{/link} und die südlichen Hügel, wo ihr Häuptling {link:grawmug}Grawmug{/link} die tiefste Höhle bewohnt. Sie haben die größte Insel des Lochs eingenommen. In {link:ironband-s-excavation-site}Ironbands Ausgrabungsstätte{/link}, wo sie zwischen den Ruinen auftauchten, beherrschen ein Häuptling namens Galgosh und ein Stammesschamane namens Magosh die Grabungen. In ihren Reihen stehen Späher, Schädelklopfer und Knochenbrecher sowie Seher, Schamanen und Geomanten, die eine rohe Magie der Erde wirken.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Die Splitterstein werden von den geschnitzten Götzenbildern der Ausgrabung angezogen, und manche von ihnen werden durch die Götzenbilder in Raserei versetzt. {link:prospector-ironband}Prospektor Ironband{/link} hofft, dass die Götzenbilder eines Tages die Verbindung zwischen den {link:troggs}Troggs{/link} und den Titanen erklären werden. Bis dahin bekämpfen die Bergsteiger des Südturms sie mit dem Wenigen, das sie haben. Sie zählen die Troggs, die sie töten, an ihren Steinzähnen.]=],
		},
	},
})

Translate("deDE", "mo-grosh-ogres", {
	title = "Mo'grosh-Oger",
	aliases = { "Mo'grosh", "Mo'grosh-Oger", "Klan Mo'grosh" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Mo'grosh sind ein Klan von {link:ogres}Ogern{/link}, die sich in den Höhlen der {link:mo-grosh-stronghold}Festung Mo'grosh{/link} im Nordosten von {link:loch-modan}Loch Modan{/link} niedergelassen haben. Keine Chronik verzeichnet, woher sie kamen oder wann sie sich dort ansiedelten.]=],
		},
		{
			title = "Ihre Art",
			text = [=[Sie sind Rohlinge, Vollstrecker und Schamanen, mit Mystikern unter ihnen, und sie folgen einem Häuptling namens {link:chok-sul}Chok'sul{/link}. Sie bauen in ihren Höhlen Kristalle ab, so selten, dass die {link:dwarves}Zwerge{/link} um einen einzigen kämpfen müssen. Sie überfallen die Straßen des Lochs, und man gibt ihnen die Schuld an Angriffen auf {link:thelsamar}Thelsamar{/link}, den Stonewroughtdamm und die Ausgrabung. Einst überfielen sie eine Erzkarawane, die aus dem {link:wetlands}Sumpfland{/link} nach Thelsamar unterwegs war, und schafften das Erz in ihr Lager.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[Der Magistrat von {link:thelsamar}Thelsamar{/link} hat Söldner angeheuert, um sie zu zerschlagen, und auf den Kopf von {link:chok-sul}Chok'sul{/link} ist ein Preis ausgesetzt. Der Magistrat will, dass zuerst mit den Ogern abgerechnet wird, damit sich die Stadt endlich gegen die {link:troggs}Troggs{/link} wenden kann.]=],
		},
	},
})

Translate("deDE", "tunnel-rat-kobolds", {
	title = "Tunnelratten-Kobolde",
	aliases = { "Tunnelratten", "Tunnelratten-Kobolde", "Tunnelrattenkobolde" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Tunnelratten sind die {link:kobolds}Kobolde{/link} von {link:loch-modan}Loch Modan{/link}. Sie sind in die Vorberge westlich von {link:thelsamar}Thelsamar{/link} gezogen und haben ihre Baue am Berghang gegraben, und sie haben die alte {link:silver-stream-mine}Silberbachmine{/link} im Norden eingenommen.]=],
		},
		{
			title = "Ihre Art",
			text = [=[Sie sind Gräber, Sammler, Späher und Vermesser, und ihre Geomanten tragen einen Feuerteer bei sich, den selbst die Schamanen des Lochs nützlich finden. In der {link:silver-stream-mine}Silberbachmine{/link} haben sie ihre Pfoten auf die Werkzeuge gelegt, die die Bergarbeiterliga dort lagerte. Die Bergsteiger würden nichts lieber tun, als einzumarschieren und sie hinauszuwerfen, doch die Liga will zuerst ihre Ausrüstung retten.]=],
		},
		{
			title = "In der Gegenwart",
			text = [=[{link:mountaineer-kadrell}Bergsteiger Kadrell{/link} zahlt ein Kopfgeld für ihre Ohren, und er bereut den Gestank. {link:mountaineer-stormpike}Bergsteiger Stormpike{/link} wartet auf den Befehl, die Mine zu säubern.]=],
		},
	},
})
